shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tests/integration_tests.rs')
text = path.read_text()
anchor = '#[test]\nfn pager_failed_to_parse() {'
assert text.count(anchor) == 1
new_tests = '''#[cfg(unix)]
#[test]
fn plain_does_not_override_paging_never() {
    for args in [
        vec!["--paging=never", "--plain"],
        vec!["--plain", "--paging=never"],
        vec!["--paging=never", "-p"],
        vec!["-p", "--paging=never"],
        vec!["--plain"],
    ] {
        let OpenptyResult { master: _master, slave } =
            openpty(None, None).expect("Couldn't open pty.");

        // A terminal exposes accidental auto paging; using bat as the pager must fail.
        bat_raw_command()
            .env("BAT_PAGING", "never")
            .env("BAT_PAGER", "bat")
            .args(args)
            .arg("test.txt")
            .stdout(Stdio::from(slave))
            .assert()
            .success()
            .stderr("");
    }
}

#[test]
#[serial]
fn plain_does_not_override_paging_always() {
    mocked_pagers::with_mocked_versions_of_more_and_most_in_path(|| {
        for args in [
            ["--paging=always", "--plain"],
            ["--plain", "--paging=always"],
            ["--paging=always", "-p"],
            ["-p", "--paging=always"],
            ["-pp", "--paging=always"],
        ] {
            bat()
                .env("PAGER", mocked_pagers::from("echo pager-output"))
                .args(args)
                .arg("test.txt")
                .assert()
                .success()
                .stdout(predicate::eq("pager-output\\n").normalize());
        }
    });
}

#[test]
fn paging_does_not_override_plain_style() {
    for args in [
        ["--plain", "--paging=never"],
        ["--plain", "--paging=always"],
        ["--plain", "--paging=auto"],
        ["-pp", "--paging=always"],
    ] {
        bat()
            .env("BAT_PAGER", "")
            .args(args)
            .arg("--decorations=always")
            .arg("--style=numbers")
            .arg("test.txt")
            .assert()
            .success()
            .stdout("hello world\\n");
    }
}

'''
path.write_text(text.replace(anchor, new_tests + anchor))
PY
RUSTFLAGS=-Awarnings cargo test --package bat --test integration_tests plain

